// INPUT PARSER - Project 3 Competitor Monitoring
// Extracts category + optional focus keyword from chat input.
// Products for each retailer are pulled by category from the program's data server.

const input = $input.first().json.chatInput || '';

const categories = [
  { key: 'area_rug',       displayName: 'Area Rug',       patterns: ['area rug', 'area rugs'] },
  { key: 'outdoor_rug',    displayName: 'Outdoor Rug',    patterns: ['outdoor rug', 'outdoor rugs', 'patio rug', 'patio rugs'] },
  { key: 'hallway_runner', displayName: 'Hallway Runner', patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners', 'hallway runners'] },
  { key: 'shag_rug',       displayName: 'Shag Rug',       patterns: ['shag rug', 'shag rugs', 'shaggy rug', 'shaggy rugs'] },
];

const lowerInput = input.toLowerCase();
let detectedCategory = null;
for (const cat of categories) {
  for (const pattern of cat.patterns) {
    if (lowerInput.includes(pattern)) {
      detectedCategory = cat;
      break;
    }
  }
  if (detectedCategory) break;
}

// Optional focus keyword (e.g. "focus: washable")
const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

const hasCategory = !!detectedCategory;
const categoryKey = detectedCategory ? detectedCategory.key : null;
const categoryDisplayName = detectedCategory ? detectedCategory.displayName : null;

return [{
  json: {
    category: categoryKey,
    categoryKey,
    categoryDisplayName,
    focus,
    hasValidInput: hasCategory,
    errorReason: hasCategory ? null : 'no_category',
    originalInput: input,
    parsedAt: new Date().toISOString(),
  }
}];

/**
 * his is the brain of Stage 1. It reads the user's chat message and figures out which rug category they want analyzed, plus an optional focus keyword. It does not handle any URLs - product data is pulled by category later in the workflow.
 Reads the chat message and detects which of the four supported rug categories it mentions: Area Rug, Outdoor Rug, Hallway Runner, or Shag Rug.
Looks for an optional focus: keyword in the message (for example, focus: washable) and pulls it out as focus.
Sets hasValidInput to true when a category is found, or false with errorReason: "no_category" when none is recognized.
Passes along categoryKey and categoryDisplayName so later nodes know exactly which category to work with.
Needs no product URLs - the actual products are fetched by category in the next stages.
 */

// Reshapes the products from the data server into the wayfair_products format the rest of the workflow expects.
// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    wayfair_products: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWayfair: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

/**
 * Reads the raw server response and pulls the products array (defaulting to an empty array if none came back).
Maps each product into a clean, predictable object: url, name, price, details, pattern, image_url, rating, review_count, and a scraped_at timestamp.
Wraps everything under the wayfair_products key, which is the exact field name downstream nodes look for.
Adds totalWayfair and totalProducts counts so later stages can report how many products were analyzed.
Falls back to the current time for scraped_at if the server didn't supply one.
 */

// The data server returns the products under a products key. This Code node maps each product into the walmartProducts[] shape that every later stage (Scope Generator, the AI analysis agents, the comparison table) expects.

